import React, { createContext, useContext } from 'react';

import { STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX } from './constants';
import { useStickyNavigationTopOffset } from './useStickyNavigationTopOffset';

const StickyNavigationTopOffsetContext = createContext(
  `${STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX}px`,
);

export const StickyNavigationTopOffsetProvider: React.FC<{
  navigationTestId: string;
  children: React.ReactNode;
}> = ({ navigationTestId, children }) => {
  const stickyTopOffset = useStickyNavigationTopOffset(navigationTestId);

  return (
    <StickyNavigationTopOffsetContext.Provider value={stickyTopOffset}>
      {children}
    </StickyNavigationTopOffsetContext.Provider>
  );
};

export const useStickyNavigationTopOffsetContext = () =>
  useContext(StickyNavigationTopOffsetContext);
